import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { execFileSync, spawnSync } from "node:child_process";
import fs from "node:fs";
import path from "node:path";
import { pathToFileURL } from "node:url";
const root = "D:/Packages/PI-Desktop/worktrees/owner-local-control", scratch = process.env.PI_SCRATCH_DIR;
const candidate = process.argv[2], base = "fd28eb89866ac513912ed109716e7120cf60f18c", prefix = "handoff-voice-native-candidate";
assert.ok(scratch); assert.match(candidate, /^[a-f0-9]{40}$/);
for (const suffix of [".json", ".log", "-shared.log", "-inputs.json"]) assert.equal(fs.existsSync(path.join(scratch, prefix + suffix)), false);
const sha = bytes => createHash("sha256").update(bytes).digest("hex");
const git = (...args) => execFileSync("git", args, { cwd: root, encoding: "utf8", maxBuffer: 8 * 1024 * 1024 }).trim();
assert.equal(git("status", "--porcelain=v1", "--untracked-files=all"), "");
assert.equal(git("rev-parse", "HEAD"), candidate); assert.equal(git("rev-parse", "origin/main"), base); git("merge-base", "--is-ancestor", base, candidate);
const files = git("ls-files", "-z", "--", "apps/desktop/electron", "apps/desktop/test", "packages/agent-host", "packages/agent-runtime", "packages/host-runtime", "packages/voice-runtime", "packages/plugin-sdk", "packages/shared", "packages/racp", "package.json", "pnpm-lock.yaml")
  .split("\0").filter(file => /\.(?:ts|tsx|js|mjs|cjs|json|html|yaml)$/.test(file)).sort();
const snapshot = () => files.map(file => { const bytes = fs.readFileSync(path.join(root, file)); return { path: file, bytes: bytes.length, sha256: sha(bytes) }; });
const inputs = snapshot(); fs.writeFileSync(path.join(scratch, prefix + "-inputs.json"), JSON.stringify(inputs, null, 2) + "\n", { flag: "wx" });
const tests = ["handoff-voice-native", "handoff-voice-controller", "handoff-audio-capture", "handoff-audio-user-path", "voice-service-idle-unload", "voice-model-download", "plugin-audio-unsupported", "main-wiring-contract"];
const sharedTests = ["test/voice-controller.test.ts", "test/pcm-utils.test.ts", "test/pcm-chunker.test.ts", "test/chinese.test.ts"];
const args = ["--import", pathToFileURL(path.join(scratch, "handoff-mcp-test-loader.mjs")).href, "--test", "--test-reporter=tap", "--test-concurrency=1", "--test-timeout=25000", ...tests.map(name => `test/${name}.test.mjs`)];
const startedAt = new Date().toISOString();
const run = (args, cwd, suffix) => {
  const result = spawnSync(process.execPath, args, { cwd, encoding: "utf8", timeout: 60000, maxBuffer: 8 * 1024 * 1024,
    env: { ...process.env, TEMP: path.resolve(scratch), TMP: path.resolve(scratch), PI_COMMAND_CENTER_DEPENDENCIES: "C:/Users/Administrator/.pi-desktop/scratch/a6fa9016-c24e-432f-8859-b0744dea889d/p0-dependencies" } });
  const log = (result.stdout ?? "") + (result.stderr ?? ""); fs.writeFileSync(path.join(scratch, prefix + suffix), log, { flag: "wx" });
  return { result: { exitCode: result.status, signal: result.signal, error: result.error?.message }, log,
    command: [process.execPath, ...args], artifact: { path: prefix + suffix, bytes: Buffer.byteLength(log), sha256: sha(log) } };
};
const desktop = run(args, path.join(root, "apps/desktop"), ".log");
const shared = run([path.join(root, "node_modules/vitest/vitest.mjs"), "run", "--config", "vitest.config.ts", "--maxWorkers=2", "--reporter=verbose", ...sharedTests], path.join(root, "packages/voice-runtime"), "-shared.log");
const report = { version: 1, status: "FAIL", candidate, base, startedAt, endedAt: new Date().toISOString(), cleanBefore: true,
  cleanAfter: git("status", "--porcelain=v1", "--untracked-files=all") === "", tests: { desktopFiles: 8, desktop: 87, sharedFiles: 4, shared: 30, unique: 117, focusedNative: 24 },
  runs: [desktop, shared].map(({ result, command, artifact }) => ({ result, command, artifact })),
  sourceInputs: { count: inputs.length, sha256: sha(JSON.stringify(inputs)), unchanged: JSON.stringify(inputs) === JSON.stringify(snapshot()), manifest: prefix + "-inputs.json", scope: "Tracked Desktop/runtime/contract sources including Voice; not a complete third-party dependency graph." },
  environment: { platform: process.platform, node: process.version, executableSha256: sha(fs.readFileSync(process.execPath)) },
  observations: desktop.log.split(/\r?\n/).filter(line => line.startsWith('# {"kind":"audio-user-path"')).map(line => JSON.parse(line.slice(2))),
  limitations: ["Actual controller, engine, model owner and audio backend use deterministic native recorder/model boundaries and isolated model files. Native streaming fixtures match the provisioned transcribe-cpp 0.2.2 asynchronous API; native frees are not observed.", "Cache download/delete lifetimes and VoiceService initialization, admission, shutdown and microphone leases remain next; full LiveVoice/remote/H1-H5 acceptance is incomplete.", "No physical microphone, native model execution, real provider/account, live Desktop/profile, stored SSH Host, download, paid API or dependency installation was used. Ordinary reset/dispose is not native-family qualification."] };
try {
  for (const run of [desktop, shared]) { assert.equal(run.result.error, undefined); assert.equal(run.result.exitCode, 0); assert.equal(run.result.signal, null); }
  for (const [key, count] of [["tests",87],["pass",87],["fail",0],["cancelled",0],["skipped",0]]) assert.match(desktop.log, new RegExp(`^# ${key} ${count}$`, "m"));
  assert.equal(new Set([...desktop.log.matchAll(/^ok \d+ - (.+)$/gm)].map(match => match[1])).size, 87);
  assert.match(shared.log.replace(/\x1b\[[0-9;]*m/g, ""), /Tests\s+30 passed/);
  assert.equal(report.observations.length, 1);
  assert.deepEqual(report.observations[0], { kind: "audio-user-path", exactPcmTranscription: true, originalReleases: 2, lateFramePublished: false,
    activity: { operations: 0, resources: 0, uncontainedResources: 2 }, nativeFamilyQualified: false, physicalMicrophoneUsed: false });
  assert.ok(report.cleanAfter && report.sourceInputs.unchanged); assert.equal(git("rev-parse", "HEAD"), candidate);
  report.status = "PASS_WITH_UNQUALIFIED_NATIVE_RESOURCES";
} catch (error) { report.error = { name: error.name, message: error.message }; }
fs.writeFileSync(path.join(scratch, prefix + ".json"), JSON.stringify(report, null, 2) + "\n", { flag: "wx" });
console.log(JSON.stringify({ status: report.status, candidate, tests: report.tests, sourceInputs: report.sourceInputs, cleanAfter: report.cleanAfter, error: report.error }, null, 2));
if (report.status === "FAIL") process.exitCode = 1;
